import asyncio, sys, json, os
from playwright.async_api import async_playwright
URL = 'http://localhost:8765/preview-mock.html'
# writes a KiCad project generated by KiLive's designer to a folder (for testing the plugin)
async def main():
    tpl, out = sys.argv[1], sys.argv[2]
    async with async_playwright() as p:
        b = await p.chromium.launch(args=['--disable-gpu'])
        pg = await b.new_page()
        logs = []
        pg.on('pageerror', lambda e: logs.append(f'PAGEERROR: {e}'))
        await pg.goto(URL + '#explore', wait_until='networkidle'); await pg.wait_for_timeout(1500)
        files = await pg.evaluate("""(tpl) => { const C = Noeti.create || Noeti.C; const T = (Noeti.create && Noeti.create.TEMPLATES) || {}; const t = T[tpl];
           const d = Noeti.designer.fromCircuit(t.circuit, { type: 'draw' }); if (t.sim) d.sim = t.sim; const r = Noeti.designer.build(d, { title: t.title });
           const out = {}; for (const [k, v] of Object.entries(r.files)) if (typeof v === 'string') out[k] = v; return out; }""", tpl)
        os.makedirs(out, exist_ok=True)
        for k, v in files.items():
            os.makedirs(os.path.dirname(os.path.join(out, k)) or out, exist_ok=True)
            open(os.path.join(out, k), 'w').write(v)
        print(sorted(files.keys()))
        print('\n'.join(logs) or 'NO ERRORS')
        await b.close()
asyncio.run(main())
